=== FILE: rr_arbiter.v ===
// rr_arbiter.v
// Round-robin arbiter for N requesters (default 4).
// Implements interface_spec.md and microarchitecture.md for rr_arbiter.
//
// * grant is one-hot or zero, only to a requester, and work conserving.
// * grant is combinational from req and the priority pointer ptr.
// * The winner is the first requester with req high at or after ptr,
//   searching upwards and wrapping from N-1 to 0.
// * On a rising edge with a grant, ptr moves to one past the winner,
//   wrapping at N (not at a power of two). With no grant, ptr holds.
// * rst_n is synchronous, active low; ptr resets to 0. grant is not gated
//   by reset.

`default_nettype none

module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output wire [N-1:0] grant
);

    localparam integer PW = (N > 1) ? $clog2(N) : 1;

    // ------------------------------------------------------------------
    // State: the priority pointer (index of the highest-priority requester)
    // ------------------------------------------------------------------
    reg  [PW-1:0] ptr;
    wire [PW-1:0] ptr_nxt;

    // ------------------------------------------------------------------
    // Grant: masked priority select, equivalent to the wrapping search.
    //   req_hi : requests at or above the pointer
    //   cand   : req_hi if any, else all requests (the wrapped part)
    //   grant  : lowest set bit of cand
    // ------------------------------------------------------------------
    wire [N-1:0] req_hi = req & ({N{1'b1}} << ptr);
    wire [N-1:0] cand   = (|req_hi) ? req_hi : req;

    assign grant = cand & (-cand);

    // ------------------------------------------------------------------
    // Next pointer: one past the winner, wrapping at N.
    // Rotating grant left by one gives the one-hot next pointer
    // (bit N-1 rotates to bit 0); encode it to an index.
    // Bit gb of ptr_nxt is the OR of rotated bits whose index has bit gb set.
    // ------------------------------------------------------------------
    genvar gb, gi;
    generate
        for (gb = 0; gb < PW; gb = gb + 1) begin : g_enc
            wire [N-1:0] sel;
            for (gi = 0; gi < N; gi = gi + 1) begin : g_req
                if (((gi >> gb) % 2) == 1) begin : g_one
                    assign sel[gi] = grant[(gi + N - 1) % N];
                end else begin : g_zero
                    assign sel[gi] = 1'b0;
                end
            end
            assign ptr_nxt[gb] = |sel;
        end
    endgenerate

    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= {PW{1'b0}};
        end else if (|grant) begin
            ptr <= ptr_nxt;
        end
    end

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Design-intent assertions (for SymbiYosys; not run by this task).
    // ------------------------------------------------------------------
    reg f_past_valid = 1'b0;
    always @(posedge clk)
        f_past_valid <= 1'b1;

    initial assume (!rst_n);

    // Index of the granted requester (0 when nothing is granted).
    reg [PW-1:0] f_winner;
    integer      f_i;
    always @(*) begin
        f_winner = {PW{1'b0}};
        for (f_i = 0; f_i < N; f_i = f_i + 1)
            if (grant[f_i])
                f_winner = f_i;
    end

    // Cyclic distance from pointer p up to requester idx.
    function integer f_dist;
        input integer idx;
        input integer p;
        begin
            f_dist = (idx + N - p) % N;
        end
    endfunction

    integer f_j;
    always @(*) begin
        // Grant is one-hot or zero, only to a requester, work conserving.
        assert ((grant & (grant - 1'b1)) == {N{1'b0}});
        assert ((grant & ~req) == {N{1'b0}});
        assert ((req == {N{1'b0}}) || (grant != {N{1'b0}}));
        if (f_past_valid) begin
            // Pointer is always in range.
            assert (ptr < N);
            // Round-robin order: no requester between ptr and the winner.
            for (f_j = 0; f_j < N; f_j = f_j + 1)
                if ((grant != {N{1'b0}}) &&
                    (f_dist(f_j, ptr) < f_dist(f_winner, ptr)))
                    assert (!req[f_j]);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n))
                assert (ptr == {PW{1'b0}});
            else if ($past(grant) != {N{1'b0}})
                assert (ptr == (($past(f_winner) + 1) % N));
            else
                assert (ptr == $past(ptr));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: rr_arbiter_tb.v ===
// rr_arbiter_tb.v
// Self-checking testbench for rr_arbiter at N=4 and N=5 (not a power of two).
// Each lane checks grant every rising edge against a reference pointer model,
// checks one-hot-or-zero, grant-only-to-requester, work conservation, and
// that no held request waits more than N-1 cycles. Coverage counters fail
// the run if a case from the interface spec was not reached.

// ----------------------------------------------------------------------
// One lane: DUT + reference model + checks + coverage, for a given N.
// ----------------------------------------------------------------------
module rr_arbiter_tb_lane #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output wire [N-1:0] grant,
    output wire [31:0]  n_pass,
    output wire [31:0]  n_fail,
    output wire [31:0]  cov_miss
);

    localparam integer ALL = (1 << N) - 1;

    rr_arbiter #(.N(N)) dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant)
    );

    // Reference model and check state (all 32-bit integers).
    integer m_ptr       = 0;
    integer req_i       = 0;
    integer grant_i     = 0;
    integer exp_i       = 0;
    integer exp_win     = 0;
    integer best        = 0;
    integer dist        = 0;
    integer k           = 0;
    integer prev_req_i  = 0;
    integer wait_cnt [0:N-1];

    integer n_pass_i    = 0;
    integer n_fail_i    = 0;

    // Coverage counters.
    integer cov_idle    = 0;
    integer cov_alone   = 0;   // mask of requesters seen requesting alone
    integer cov_all     = 0;
    integer cov_maxwait = 0;
    integer cov_held    = 0;
    integer cov_rst     = 0;

    reg armed    = 1'b0;   // set once reset has been applied
    reg seen_run = 1'b0;   // set once out of reset after arming

    assign n_pass = n_pass_i;
    assign n_fail = n_fail_i;
    assign cov_miss = {26'd0,
                       (cov_rst == 0),
                       (cov_held == 0),
                       (cov_maxwait == 0),
                       (cov_all < N),
                       (cov_alone != ALL),
                       (cov_idle == 0)};

    always @(posedge clk) begin
        req_i   = {{(32-N){1'b0}}, req};
        grant_i = {{(32-N){1'b0}}, grant};

        // Reference: first request at or after the pointer, wrapping at N.
        exp_win = -1;
        best    = N;
        for (k = 0; k < N; k = k + 1) begin
            if (((req_i >> k) & 1) != 0) begin
                dist = (k - m_ptr + N) % N;
                if (dist < best) begin
                    best    = dist;
                    exp_win = k;
                end
            end
        end
        exp_i = (exp_win >= 0) ? (1 << exp_win) : 0;

        if (armed) begin
            // 1. Grant matches the reference pointer model.
            if (grant_i == exp_i) begin
                n_pass_i = n_pass_i + 1;
            end else begin
                n_fail_i = n_fail_i + 1;
                $error("rr_arbiter N=%0d: grant 'h%0h, model expects 'h%0h (req 'h%0h, model pointer %0d)",
                       N, grant_i, exp_i, req_i, m_ptr);
            end

            // 2. One-hot or zero.
            if ((grant_i & (grant_i - 1)) == 0) begin
                n_pass_i = n_pass_i + 1;
            end else begin
                n_fail_i = n_fail_i + 1;
                $error("rr_arbiter N=%0d: grant 'h%0h is not one-hot or zero", N, grant_i);
            end

            // 3. Only to a requester.
            if ((grant_i & ~req_i) == 0) begin
                n_pass_i = n_pass_i + 1;
            end else begin
                n_fail_i = n_fail_i + 1;
                $error("rr_arbiter N=%0d: grant 'h%0h to a non-requester (req 'h%0h)", N, grant_i, req_i);
            end

            // 4. Work conserving.
            if ((req_i == 0) || (grant_i != 0)) begin
                n_pass_i = n_pass_i + 1;
            end else begin
                n_fail_i = n_fail_i + 1;
                $error("rr_arbiter N=%0d: req 'h%0h but no grant", N, req_i);
            end

            if (rst_n) begin
                // 5. Fairness: a held request waits at most N-1 cycles.
                for (k = 0; k < N; k = k + 1) begin
                    if ((((req_i >> k) & 1) != 0) && (((grant_i >> k) & 1) == 0)) begin
                        wait_cnt[k] = wait_cnt[k] + 1;
                        if (wait_cnt[k] <= N - 1) begin
                            n_pass_i = n_pass_i + 1;
                        end else begin
                            n_fail_i = n_fail_i + 1;
                            $error("rr_arbiter N=%0d: requester %0d has waited %0d cycles (bound %0d)",
                                   N, k, wait_cnt[k], N - 1);
                        end
                        if (((req_i ^ prev_req_i) & ~(1 << k)) != 0)
                            cov_held = cov_held + 1;
                    end else begin
                        if ((((grant_i >> k) & 1) != 0) && (wait_cnt[k] == N - 1))
                            cov_maxwait = cov_maxwait + 1;
                        wait_cnt[k] = 0;
                    end
                end

                // Coverage of stimulus cases.
                if (req_i == 0)
                    cov_idle = cov_idle + 1;
                if (req_i == ALL)
                    cov_all = cov_all + 1;
                if ((req_i != 0) && ((req_i & (req_i - 1)) == 0))
                    cov_alone = cov_alone | req_i;
            end else begin
                if (seen_run && (req_i != 0))
                    cov_rst = cov_rst + 1;
            end
        end

        // Model state update (mirrors the synchronous pointer).
        if (!rst_n) begin
            for (k = 0; k < N; k = k + 1)
                wait_cnt[k] = 0;
            m_ptr = 0;
            armed = 1'b1;
        end else if (exp_win >= 0) begin
            m_ptr = (exp_win + 1) % N;
        end
        if (armed && rst_n)
            seen_run = 1'b1;
        prev_req_i = req_i;
    end

endmodule

// ----------------------------------------------------------------------
// Top: drives both lanes, collects results, prints the verdict.
// ----------------------------------------------------------------------
module rr_arbiter_tb;

    reg        clk   = 1'b0;
    reg        rst_n = 1'b0;
    reg  [3:0] req4  = 4'd0;
    reg  [4:0] req5  = 5'd0;
    wire [3:0] grant4;
    wire [4:0] grant5;
    wire [31:0] pass4;
    wire [31:0] fail4;
    wire [31:0] miss4;
    wire [31:0] pass5;
    wire [31:0] fail5;
    wire [31:0] miss5;

    reg [8*64-1:0] nonce;
    integer passed;
    integer failed;
    integer got;
    integer cyc;
    integer r;
    integer held;

    always #5 clk = ~clk;

    rr_arbiter_tb_lane #(.N(4)) u_n4 (
        .clk      (clk),
        .rst_n    (rst_n),
        .req      (req4),
        .grant    (grant4),
        .n_pass   (pass4),
        .n_fail   (fail4),
        .cov_miss (miss4)
    );

    rr_arbiter_tb_lane #(.N(5)) u_n5 (
        .clk      (clk),
        .rst_n    (rst_n),
        .req      (req5),
        .grant    (grant5),
        .n_pass   (pass5),
        .n_fail   (fail5),
        .cov_miss (miss5)
    );

    // Apply one cycle of stimulus at the falling edge; checked at the next rise.
    task step;
        input integer rn;
        input integer v4;
        input integer v5;
        begin
            @(negedge clk);
            rst_n = rn[0];
            req4  = v4[3:0];
            req5  = v5[4:0];
        end
    endtask

    initial begin
        passed = 0;
        failed = 0;

        // 1. Reset with no requests.
        repeat (3) step(0, 0, 0);

        // 2. No requests.
        repeat (4) step(1, 0, 0);

        // 3. Each requester alone.
        for (cyc = 0; cyc < 5; cyc = cyc + 1) begin
            step(1, 1 << cyc, 1 << cyc);
            step(1, 1 << cyc, 1 << cyc);
        end

        // 4. Everyone requesting: strict rotation, longest fair wait N-1.
        repeat (15) step(1, 15, 31);

        // 5. Reset during traffic, then everyone requesting from reset.
        repeat (2) step(0, 15, 31);
        repeat (12) step(1, 15, 31);

        // 6. A held request among changing others.
        for (cyc = 0; cyc < 250; cyc = cyc + 1) begin
            held = (cyc / 25) % 5;
            r = $random;
            step(1, r | (1 << held), (r >> 4) | (1 << held));
        end

        // 7. Random traffic (dense and sparse) with reset pulses.
        for (cyc = 0; cyc < 400; cyc = cyc + 1) begin
            if ((cyc % 2) == 0)
                r = $random;
            else
                r = $random & $random;
            step(((cyc % 97) == 50) ? 0 : 1, r, r >> 5);
        end

        // 8. Drain and let the last stimulus be checked.
        step(1, 0, 0);
        @(posedge clk);
        @(negedge clk);

        passed = pass4 + pass5;
        failed = fail4 + fail5;

        // Coverage: every case from the interface spec must be reached.
        if (miss4 == 32'd0) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $error("N=4: coverage not reached, missing 'b%b (bit0 idle, 1 each alone, 2 all, 3 longest wait, 4 held among changing, 5 reset in traffic)",
                   miss4[5:0]);
        end
        if (miss5 == 32'd0) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $error("N=5: coverage not reached, missing 'b%b (bit0 idle, 1 each alone, 2 all, 3 longest wait, 4 held among changing, 5 reset in traffic)",
                   miss5[5:0]);
        end

        nonce = {(8*64){1'b0}};
        got = $value$plusargs("nirmaan_nonce=%s", nonce);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
